shell_commands:
node -e "
import('@re-cinq/eslint-plugin-re-lint').then(m => {
  const rules = m.default.rules;
  for (const name of ['require-colocated-tests', 'test-imports-its-subject', 'require-spec-link', 'max-expects', 'no-nondeterministic-tests']) {
    console.log('=== ' + name + ' ===');
    console.log(rules[name].meta?.docs);
  }
});
"

node -e "
import('node:fs').then(fs => {
  for (const f of ['require-colocated-tests.js', 'test-imports-its-subject.js', 'require-spec-link.js']) {
    const matches = fs.globSync('node_modules/@re-cinq/eslint-plugin-re-lint/**/' + f);
    console.log('=== ' + f + ' ===', matches);
    if (matches[0]) console.log(fs.readFileSync(matches[0], 'utf8'));
  }
});
"

node -e "
import('@re-cinq/eslint-plugin-re-lint').then(m => {
  for (const [k, v] of Object.entries(m.default.rules)) {
    console.log(k + ':', v.meta?.docs?.description);
  }
});
"
